using System.Collections.Immutable;
using System.Text;
using Extensions.Pack;

namespace AspNetCore.MinimalApi.Sdk.CodeRules.Fixtures
{
    [TestCategory("Coding-Rules Fixtures")]
    // [TestCategory("AsyncAwait")]
    [TestCategory("RJIT_CR_AA_S")]
    [TestClass]
    public class RJIT_CR_AA_S_00002 : MsTestBase
    {
        private sealed record AnalyzedCodeResult(string ErrorMethod, string ErrorMethodValue);
        private IImmutableList<AnalyzedCodeResult> CodeRule()
        {
            var analyzedCode = (from @struct in Structs
                from @method in @struct.Methods
                where method.Statements.Count < 2 && method.MethodBody.Contains("await") &&
                      method.LineStatements.Count < 2
                select new AnalyzedCodeResult(method.Name, method.MethodValue)).ToImmutableList();
            return analyzedCode;
        }
        
        [TestMethod]
        public async Task Should_SelfHealAsync()
        {
            var codeRuleResult = CodeRule();
            foreach (var errors in codeRuleResult)
            {
                var cSharpFiles = Solution.Projects.SelectMany(p => p.CSharpFileInfos).ToList();
                foreach (var allSyntax in cSharpFiles)
                {
                    var fileContent = await File.ReadAllTextAsync(allSyntax.Value.FullName).ConfigureAwait(false);
                    if (fileContent.Contains(errors.ErrorMethod))
                    {
                        var baseMethod = errors.ErrorMethodValue;
                        var cleanedMethod = errors.ErrorMethodValue.Replace("return await", "return").Replace(".ConfigureAwait(false)", string.Empty).Replace(".ConfigureAwait(true)", string.Empty);
                        if (cleanedMethod.DoesNotContain("await"))
                        {
                            cleanedMethod = cleanedMethod.Replace("async ", "");
                        }
                        var modifiedContent = fileContent.Replace(baseMethod, cleanedMethod);
                        
                        await File.WriteAllTextAsync(allSyntax.Value.FullName, modifiedContent, new UTF8Encoding())
                            .ConfigureAwait(false);
                    }
                }
            }
        }
    }
